import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import './Inscripcion.css';

const Inscripcion = ({ cursoId }) => {
  const navigate = useNavigate();
  
  // Estado para el formulario
  const [formData, setFormData] = useState({
    nombre: '',
    email: '',
    telefono: '',
    edad: '',
    respuestas: [], // Array para guardar las respuestas
  });

  const [preguntas, setPreguntas] = useState([]); // Estado para las preguntas
  const [opciones, setOpciones] = useState([]);   // Estado para las opciones

  // Estado para controlar si la inscripción fue exitosa
  const [isInscribed, setIsInscribed] = useState(false);

  // Cargar las preguntas y opciones desde el backend
  useEffect(() => {
    const fetchPreguntasYOpciones = async () => {
      const response = await fetch('http://localhost:3001/api/preguntas'); // Aquí la URL para obtener las preguntas
      const data = await response.json();
      if (response.ok) {
        setPreguntas(data.preguntas);  // Suponiendo que las preguntas y las opciones vienen en la respuesta
        setOpciones(data.opciones);
      } else {
        alert('Error al cargar las preguntas');
      }
    };
    fetchPreguntasYOpciones();
  }, []);

  // Manejar los cambios en los campos del formulario
  const handleChange = (e) => {
    const { name, value } = e.target;
    if (name.startsWith('respuesta')) {
      const index = parseInt(name.replace('respuesta', '')) - 1;
      const newRespuestas = [...formData.respuestas];
      newRespuestas[index] = value;
      setFormData((prevData) => ({
        ...prevData,
        respuestas: newRespuestas,
      }));
    } else {
      setFormData((prevData) => ({
        ...prevData,
        [name]: value,
      }));
    }
  };

  // Enviar los datos al backend para crear la inscripción
  const handleSubmit = async (e) => {
    e.preventDefault();

    const response = await fetch('http://localhost:3001/api/usuarios/inscribirse', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        ...formData,
        cursoId: cursoId, // Enviar el ID del curso seleccionado
      }),
    });

    const data = await response.json();

    if (response.ok) {
      // Si la inscripción fue exitosa, mostrar el mensaje y ocultar el formulario
      setIsInscribed(true);
      // Redirigir a la página de pago con el cursoId
      setTimeout(() => {
        navigate(`/pago/${cursoId}`); // Redirigimos usando navigate
      }, 2000); // Redirige después de 2 segundos para mostrar el mensaje
    } else {
      alert('Error al inscribirse');
    }
  };

  return (
    <div className="inscripcion">
      {!isInscribed ? (
        <>
          <h2>Inscripción al Curso</h2>
          <form onSubmit={handleSubmit}>
            <input
              type="text"
              name="nombre"
              placeholder="Nombre"
              value={formData.nombre}
              onChange={handleChange}
            />
            <input
              type="email"
              name="email"
              placeholder="Email"
              value={formData.email}
              onChange={handleChange}
            />
            <input
              type="text"
              name="telefono"
              placeholder="Teléfono"
              value={formData.telefono}
              onChange={handleChange}
            />
            <input
              type="number"
              name="edad"
              placeholder="Edad"
              value={formData.edad}
              onChange={handleChange}
            />

            {/* Aquí renderizamos las preguntas y sus opciones */}
            {preguntas.map((pregunta, index) => (
              <div key={pregunta.id} className="pregunta">
                <h3>{pregunta.texto}</h3> {/* Aquí mostramos el texto de la pregunta */}
                <div>
                  {opciones
                    .filter((opcion) => opcion.pregunta_id === pregunta.id) // Filtramos las opciones según la pregunta
                    .map((opcion) => (
                      <label key={opcion.id}>
                        <input
                          type="radio"
                          name={`respuesta${index + 1}`} // Nombre único para cada grupo de radio buttons
                          value={opcion.id}
                          checked={formData.respuestas[index] === opcion.id}
                          onChange={handleChange}
                        />
                        {opcion.texto}
                      </label>
                    ))}
                </div>
              </div>
            ))}

            <button type="submit">Inscribirse</button>
          </form>
        </>
      ) : (
        <div className="inscripcion-exitosa">
          <h3>¡Inscripción exitosa!</h3>
          <p>Por favor revisa tu correo para acceder al curso.</p>
        </div>
      )}
    </div>
  );
};

export default Inscripcion;
